object State extends ChiselEnum {
  val sIdle, sSrcmd, sMdcfg, sMdcfgPre, sEntry, sPriority, sMatching, sErr, sDone = Value
}

is(State.sIdle) { when(io.req.fire) { when(io.reg.o_reg_hwcfg0_enable === 1.U) { when(io.req.bits.rrid < io.reg.o_reg_hwcfg1_rrid_num){ state:= State.sSrcmd } ... } } }
is(State.sPriority) { when(pri_hit) { state := State.sMatching }.elsewhen(pri_part_hit) { etype := 0x4.U; state := State.sErr }.elsewhen(j_indx === md_t){ state := State.sMdcfg } }
is(State.sMatching) { when(req.rw && !entry_attribute.w || io.reg.o_reg_hwcfg0_no_w.asBool) { etype := 0x2.U; state := State.sErr } ... }

object NAPOTDecoder {
  def apply(entry_addr: UInt): (UInt, UInt) = {
    val trailing_ones = Wire(UInt(log2Ceil(IopmpParams.soc_addr_width).W))
    trailing_ones := PriorityEncoder(~entry_addr)
    val size = trailing_ones + 1.U
    val mask = (1.U << size) - 1.U
    addr_start := entry_addr & (~mask).asUInt
    addr_end := addr_start + mask
    (addr_start, addr_end)
  }
}

val (addr_start, addr_end) = NAPOTDecoder(entry_addr)
when(io.entry.attribute.a === 0x2.U || io.entry.attribute.a === 0x3.U) {
  val pa_end = req.pa + req.len - 1.U
  when(pa_end < addr_start || req.pa > addr_end){ pri_hit := false.B; pri_part_hit := false.B }
  .elsewhen(req.pa >= addr_start && pa_end <= addr_end) { pri_hit := true.B; pri_part_hit := false.B }
  .otherwise { pri_hit := false.B; when(j_indx_d < io.reg.o_reg_hwcfg2_prio_entry) { pri_part_hit := true.B } }
}

