class IopmpLazy(numBridge: Int = 1)(implicit p: Parameters) extends LazyModule {
  val checker = LazyModule(new IopmpChecker)
  val apb = LazyModule(new APB2Reg)
  val bridge = Seq.tabulate(numBridge) { i => LazyModule(new IopmpBridgeLazy(i, beatBytes = checker.axi_beatBytes)) }
  // No IOATC, no DDT/PDT walker, no IOTINVAL command path
}
